public sealed interface PaymentOutcome
    permits Settled, Declined, Pending, Failed {

    // One line each. The Java 8 version of this was forty, which is why
    // people used maps and lost the types entirely.
    record Settled(String reference, long amountMinor) implements PaymentOutcome {}
    record Declined(String code, boolean retryable) implements PaymentOutcome {}
    record Pending(Instant expectedBy) implements PaymentOutcome {}
    record Failed(String message) implements PaymentOutcome {}
}

public String describe(PaymentOutcome outcome) {
    // No default branch. Add a fifth outcome and this stops compiling, which
    // is the entire reason the interface is sealed.
    return switch (outcome) {
        case Settled(String ref, long amount) ->
            "Settled %s (%d)".formatted(ref, amount);

        // Guarded pattern: the condition is part of the match, not an if
        // nested inside the branch.
        case Declined(String code, boolean retryable) when retryable ->
            "Declined (%s) - retrying".formatted(code);
        case Declined(String code, boolean ignored) ->
            "Declined (%s) - do not retry".formatted(code);

        case Pending(Instant by) ->
            "Awaiting confirmation until %s".formatted(by);
        case Failed(String message) ->
            "Failed: %s".formatted(message);
    };
}
